\begin{tikzpicture}
\begin{axis}[
    width=0.82\textwidth,
    height=0.48\textwidth,
    xmin=0, xmax=4.2,
    ymin=-0.3, ymax=2.4,
    axis lines=left,
    xlabel={\(t\)},
    ylabel={\(y(t)\)},
    xtick={0,1,2,3,4},
    ytick={0,1,2},
    grid=both,
    grid style={line width=.1pt, draw=gray!25},
    legend style={draw=none, fill=none, at={(0.5,-0.20)}, anchor=north, legend columns=3, font=\small}
]
\addplot[very thick, domain=0:4, samples=150] {1-exp(-x)};
\addlegendentry{\(y(0)=0\)}
\addplot[very thick, dashed, domain=0:4, samples=150] {1+exp(-x)};
\addlegendentry{\(y(0)=2\)}
\addplot[thick, dotted, domain=0:4, samples=2] {1};
\addlegendentry{\(y=1\)}
\addplot[only marks, mark=*] coordinates {(0,0) (0,2)};
\node[anchor=west] at (axis cs:2.3,1.55) {same equation};
\node[anchor=west] at (axis cs:2.3,1.32) {different initial values};
\end{axis}
\end{tikzpicture}
